use super::Stage;
#[test]
fn neutral_stage_contract_has_every_retained_frontier(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let actual=[Stage::Birth,Stage::Decide,Stage::Source,Stage::Plan,Stage::Preflight,Stage::Inverse,Stage::Commit,Stage::Join,Stage::Publish,Stage::Done].map(|stage|format!("{stage:?}"));assert_eq!(actual.to_vec(),fixture["stages"].as_array().unwrap().iter().map(|value|value.as_str().unwrap().to_string()).collect::<Vec<_>>());for flow in ["admitted","decisionRefused","preflightRefused"]{let values=fixture[flow].as_array().unwrap();assert_eq!(values.first().unwrap(),"Birth");assert_eq!(values.last().unwrap(),"Done");if flow!="admitted"{assert!(!values.iter().any(|value|value=="Commit"));}}}
